/**
 * If-Match is the list form (IfMatchList): one quoted version per item in items[] order, equal to items[].version. Missing → 428; a stale version → 412 version_mismatch listing the stale items in errors[] (path items.N.version); nothing is written. Only TagPatch fields; location → moves, weights → adjustments.
 * @summary Same descriptive change on up to 200 tags, each guarded by its version, all-or-nothing (inventory.tag.edit)
 */
export const bulkUpdateTagsHeaderIfMatchRegExp = new RegExp('^(W/)?\"[0-9]+\"(\\s*,\\s*(W/)?\"[0-9]+\")*$');


export const bulkUpdateTagsHeader = zod.object({
  "If-Match": zod.string().regex(bulkUpdateTagsHeaderIfMatchRegExp).describe('Bulk form (RFC 9110 list): one quoted ETag per item, in items[] order, e.g. `\"3\", \"7\"`. Each must equal that item\'s items[].version. Missing → 428; wrong count / disagreeing with items[] / stale → 412 version_mismatch (stale items listed in errors[] as items.N.version); nothing changes.')
})

