/**
 * 409 feature_disabled when ageing is off. Age = today (IST) − since, where since = COALESCE(tag.received_on, IST date of tagged_at); age_basis (received | tagged) says which one was used. Written-off and other terminal pieces are excluded. Buckets are computed by the server from settings.ageing_bucket_days (lower bounds; default 30, 90, 180, 365 → 0–29, 30–89, 90–179, 180–364, 365+ days). The first bucket always starts at 0 days and ends at (first bound − 1); each bucket has a stable code and an English label.
 * @summary Ageing of in-stock pieces by bucket (optional feature: settings.ageing_enabled) (inventory.ageing.view)
 */
export const getStockAgeingReportQueryGroupByDefault = "item";export const getStockAgeingReportQueryIncludeRowsDefault = false;export const getStockAgeingReportQueryLimitDefault = 50;
export const getStockAgeingReportQueryLimitMax = 200;

export const getStockAgeingReportQueryParams = zod.object({
  "branch_id": zod.string().uuid().optional().describe('Optional; falls back to the X-Branch-Id header, then to every branch the caller can see. Branch-scoped users only see their branches (403 branch_scope).'),
  "group_by": zod.enum(['item', 'design', 'purity', 'counter']).default(getStockAgeingReportQueryGroupByDefault),
  "include_rows": zod.boolean().optional(),
  "limit": zod.number().min(1).max(getStockAgeingReportQueryLimitMax).default(getStockAgeingReportQueryLimitDefault),
  "cursor": zod.string().optional()
})

export const getStockAgeingReportHeader = zod.object({
  "X-Branch-Id": zod.string().uuid().optional().describe('Active branch sent by the web client; used when branch_id is not given')
})

export const getStockAgeingReportResponseGroupsItemBucketsItemFromDaysMin = 0;export const getStockAgeingReportResponseGroupsItemBucketsItemPiecesMin = 0;export const getStockAgeingReportResponseGroupsItemBucketsItemGrossWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const getStockAgeingReportResponseGroupsItemBucketsItemNetWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const getStockAgeingReportResponseGroupsItemOldestDaysMin = 0;export const getStockAgeingReportResponseTotalsItemFromDaysMin = 0;export const getStockAgeingReportResponseTotalsItemPiecesMin = 0;export const getStockAgeingReportResponseTotalsItemGrossWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const getStockAgeingReportResponseTotalsItemNetWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const getStockAgeingReportResponseRowsItemAgeDaysMin = 0;export const getStockAgeingReportResponseRowsItemGrossWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const getStockAgeingReportResponseRowsItemNetWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');


